// Get HTML from Fetch Homepage
const html = $input.item.json.body || $input.item.json.data || '';

// Extract URL from the headers link or construct from current data
let websiteUrl = '';

// Try to get URL from headers.link or construct it
const headers = $input.item.json.headers || {};
const linkHeader = headers.link || '';

if (linkHeader) {
  const match = linkHeader.match(/<(https?:\/\/[^>]+)>/);
  if (match) websiteUrl = match[1];
}

// If not found, try to extract base URL from HTML
if (!websiteUrl && html) {
  const canonicalMatch = html.match(/<link[^>]*rel=["']canonical["'][^>]*href=["']([^"']+)["']/);
  if (canonicalMatch) {
    websiteUrl = canonicalMatch[1].trim();
    // Handle protocol-relative URLs
    if (websiteUrl.startsWith('//')) {
      websiteUrl = 'https:' + websiteUrl;
    }
    // Ensure URL has a protocol
    if (!websiteUrl.startsWith('http://') && !websiteUrl.startsWith('https://')) {
      websiteUrl = 'https://' + websiteUrl;
    }
  }
}

if (!websiteUrl) {
  throw new Error('Could not determine website URL from response');
}

// Clean and validate the URL
websiteUrl = websiteUrl.trim().replace(/[\r\n\t]/g, '');

// Extract origin from URL
let baseUrl = '';
try {
  const urlObj = new URL(websiteUrl);
  baseUrl = urlObj.origin;
} catch (error) {
  // Fallback: try to extract domain manually
  const domainMatch = websiteUrl.match(/^(https?:\/\/[^\/]+)/);
  if (domainMatch) {
    baseUrl = domainMatch[1];
  } else {
    throw new Error(`Could not parse URL: ${websiteUrl}`);
  }
}

// Start with the base URL
const urls = [baseUrl];

// Extract all href links from HTML
const allHrefs = html.split('href=');

for (let i = 1; i < allHrefs.length && urls.length < 20; i++) {
  const part = allHrefs[i];
  let url = '';

  // Extract URL from quotes
  if (part[0] === '"') {
    const end = part.indexOf('"', 1);
    if (end > 0) url = part.substring(1, end);
  } else if (part[0] === "'") {
    const end = part.indexOf("'", 1);
    if (end > 0) url = part.substring(1, end);
  }

  // Skip anchors, mailto, tel links
  if (!url || url[0] === '#' || url.startsWith('mailto:') || url.startsWith('tel:')) {
    continue;
  }

  // Convert relative URLs to absolute
  if (url.startsWith('//')) {
    // Protocol-relative URL
    url = 'https:' + url;
  } else if (url[0] === '/') {
    // Path-relative URL
    url = baseUrl + url;
  } else if (!url.startsWith('http')) {
    continue;
  }

  // Skip xmlrpc, wp-json, feed, and other non-page URLs
  if (url.indexOf('xmlrpc') >= 0 || url.indexOf('wp-json') >= 0 || 
      url.indexOf('/feed') >= 0 || url.indexOf('.xml') >= 0 || 
      url.indexOf('.json') >= 0 || url.indexOf('.rss') >= 0) {
    continue;
  }

  // Only keep URLs from same domain
  if (url.startsWith(baseUrl)) {
    // Remove query params and hash
    const qPos = url.indexOf('?');
    const hPos = url.indexOf('#');
    if (qPos > 0) url = url.substring(0, qPos);
    if (hPos > 0) url = url.substring(0, hPos);

    // Check for duplicates
    if (!urls.includes(url)) {
      urls.push(url);
    }
  }
}

// Return array of URLs as separate items for processing
return urls.map(u => ({ json: { url: u } }));

