var items = $input.all();
var parts = [];

for (var i = 0; i < items.length; i++) {
  if (items[i] && items[i].json && items[i].json.pageHtml) {
    parts.push(items[i].json.pageHtml);
  }
}

var result = parts.length > 0 ? parts.join('\n\n') : 'No HTML content extracted';

return [{ json: { allPagesHtml: result } }];
